+// Picks the language of a response from the request's Accept-Language header.
+import { LANGUAGES } from "../i18n/messages.js";
+
+function headerValue(headers, name) {
+  for (const [k, v] of Object.entries(headers ?? {})) {
+    if (k.toLowerCase() === name) return Array.isArray(v) ? v.join(",") : v;
+  }
+  return undefined;
+}
+
+/** The supported language the request prefers (highest q first, region tags ignored), else `fallback`. */
+export function requestLanguage(headers, fallback) {
+  const header = headerValue(headers, "accept-language");
+  if (typeof header !== "string") return fallback;
+  let best = null;
+  let bestQ = 0;
+  for (const part of header.split(",")) {
+    const [range, ...rest] = part.split(";").map((s) => s.trim());
+    const lang = range.toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(lang)) continue;
+    let q = 1;
+    const qParam = rest.find((p) => /^q\s*=/i.test(p));
+    if (qParam !== undefined) {
+      const raw = qParam.slice(qParam.indexOf("=") + 1).trim();
+      if (!/^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(raw)) continue;
+      q = Number(raw);
+    }
+    if (q > bestQ) {
+      best = lang;
+      bestQ = q;
+    }
+  }
+  return best ?? fallback;
+}
